private async run(row: ErasureRequestRow): Promise<ErasureRequestRow> {
  const processing = await this.repository.markProcessing(row.id); // attempts+1, status processing, last_error null
  try {
    const objectKeys = await transaction(async (client) => {
      const keys = await this.repository.eraseCustomerData(client, row.merchant_id, row.customer_id);
      await addOutboxEvent(client, { eventType: EVENT_TYPES.CUSTOMER_ERASED, aggregateType: 'customer', aggregateId: row.customer_id, merchantId: row.merchant_id, correlationId: uuid(), payload: { customerId: row.customer_id, erasureRequestId: row.id } });
      return keys;
    });
    await this.deleteObjects(objectKeys); // best effort
    return await this.repository.markCompleted(row.id);
  } catch (error) {
    logger.error(...)
    return await this.repository.markFailed(row.id, ERASURE_FAILURE_CODE);
  }
}
```

