{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  idempotency_key: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export class ErasureRepository {
  async customerExists(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`, [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`, [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByKey(merchantId: string, key: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2`, [merchantId, key],
    );
    return result.rows[0];
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    return result.rows[0];
  }

  async create(merchantId: string, customerId: string, key: string): Promise<ErasureRequestRow> {
    const result = await pool.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3)
       ON CONFLICT(merchant_id,customer_id) DO NOTHING
       RETURNING *`,
      [merchantId, customerId, key],
    );
    if (result.rows[0]) return result.rows[0];
    const existing = await this.findByCustomer(merchantId, customerId);
    if (!existing) throw new Error('erasure request could not be created');
    return existing;
  }

  async markProcessing(requestId: string): Promise<ErasureRequestRow> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,last_error=NULL,updated_at=now()
       WHERE id=$1 RETURNING *`,
      [requestId],
    );
    return result.rows[0]!;
  }

  async markCompleted(requestId: string): Promise<ErasureRequestRow> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='completed',last_error=NULL,completed_at=now(),updated_at=now()
       WHERE id=$1 RETURNING *`,
      [requestId],
    );
    return result.rows[0]!;
  }

  async markFailed(requestId: string, errorCode: string): Promise<ErasureRequestRow> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='failed',last_error=$2,updated_at=now()
       WHERE id=$1 RETURNING *`,
      [requestId, errorCode],
    );
    return result.rows[0]!;
  }

  /**
   * Removes or anonymizes every PayFlow-controlled copy of the customer's personal data while
   * keeping financial records (payments, invoices, ledger) intact and financially correct.
   * Every statement is idempotent so a failed attempt can safely resume. Returns the object
   * storage keys whose contents must be deleted outside the transaction.
   */
  async eraseCustomerData(client: pg.PoolClient, merchantId: string, customerId: string): Promise<string[]> {
    // Suppress queued work that would republish or re-deliver customer PII after deletion.
    await client.query(
      `UPDATE operations.outbox_events SET status='published',published_at=now(),last_error=NULL
       WHERE merchant_id=$1 AND status='pending' AND aggregate_type='customer' AND aggregate_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.outbox_events
       SET payload=payload - 'customerEmail' - 'customerSnapshot' - 'email' - 'name' - 'phone'
       WHERE merchant_id=$1 AND status='pending' AND payload->>'customerId'=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.jobs
       SET payload=payload - 'customerEmail' - 'customerSnapshot' - 'email' - 'name' - 'phone'
       WHERE merchant_id=$1 AND status='pending' AND payload->>'customerId'=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.dead_letters
       SET payload=payload - 'customerEmail' - 'customerSnapshot' - 'email' - 'name' - 'phone'
       WHERE payload->>'merchantId'=$1 AND payload->>'customerId'=$2 AND resolved_at IS NULL`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.email_deliveries
       SET status='cancelled',cancelled_at=now(),last_error=NULL
       WHERE merchant_id=$1 AND customer_id=$2 AND status IN ('pending','processing','failed')`,
      [merchantId, customerId],
    );

    // Customer profile and directly identifying records.
    await client.query(
      `DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `UPDATE customers.payment_method_refs
       SET provider_token='erased-'||id::text,billing_name=NULL,billing_address=NULL,last4=NULL,status='erased'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.support_participants
       WHERE customer_id=$2 AND ticket_id IN (SELECT id FROM customers.support_tickets WHERE merchant_id=$1)`,
      [merchantId, customerId],
