import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';

export const ERASURE_FAILURE_CODE = 'erasure_cleanup_failed';

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  /**
   * Starts or resumes a data deletion request. Idempotent per merchant: an idempotency key always
   * maps to one request, and a customer has at most one request. Failed requests are retried in
   * place, keeping the same request ID.
   */
  async request(merchantId: string, customerId: string, key: string): Promise<ErasureRequestRow> {
    if (!await this.repository.customerExists(merchantId, customerId)) {
      throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
    }
    const byKey = await this.repository.findByKey(merchantId, key);
    if (byKey && byKey.customer_id !== customerId) {
      throw Object.assign(new Error('idempotency_key_conflict'), { statusCode: 409 });
    }
    const existing = byKey ?? await this.repository.findByCustomer(merchantId, customerId);
    if (existing) {
      return existing.status === 'failed' ? this.run(existing) : existing;
    }
    const created = await this.repository.create(merchantId, customerId, key);
    if (created.status !== 'pending' || created.idempotency_key !== key) {
      // A concurrent request created the customer's workflow first; return that request.
      return created.status === 'failed' ? this.run(created) : created;
    }
    const processed = await this.run(created);
    // Present the request as accepted: cleanup continues asynchronously from the caller's view.
    return { ...processed, status: 'pending', attempts: created.attempts, completed_at: null, last_error: null };
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    return this.repository.findById(merchantId, requestId);
  }

  private async run(row: ErasureRequestRow): Promise<ErasureRequestRow> {
    await this.repository.markProcessing(row.id);
    try {
      const objectKeys = await transaction(async (client) => {
        const keys = await this.repository.eraseCustomerData(client, row.merchant_id, row.customer_id);
        await addOutboxEvent(client, {
          eventType: EVENT_TYPES.CUSTOMER_ERASED, aggregateType: 'customer', aggregateId: row.customer_id,
          merchantId: row.merchant_id, correlationId: uuid(),
          payload: { customerId: row.customer_id, erasureRequestId: row.id },
        });
        return keys;
      });
      await this.deleteStoredObjects(objectKeys);
      return await this.repository.markCompleted(row.id);
    } catch (error) {
      logger.error({ err: error, erasureRequestId: row.id }, 'erasure attempt failed');
      return this.repository.markFailed(row.id, ERASURE_FAILURE_CODE);
    }
  }

  private async deleteStoredObjects(objectKeys: string[]): Promise<void> {
    for (const objectKey of objectKeys) {
      await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
    }
  }
}
"}

